import {strategyLearning} from './strategy-learning-view.mjs';
import {planValuation,planRanges,valuationModelRoute} from './plan-visual.mjs';
import {investmentInline} from './investment-view.mjs';
import {feeObservationPanel} from './fee-observation.mjs';
import {eventScenario} from './scenario-context.mjs';
import {liveStatus,liveDetails} from './daily-live.mjs';
import {pathCards,pathPreview} from './market-paths.mjs';
import {HORIZONS,reviewYears,reviewDay,reviewLabel} from './timeline.mjs';
// Presentation layer only. All portfolio values come from the existing simulator.
import {feeHistoryPanel} from './live-fees-view.mjs';
import {currentHoldings,compactHoldings,lifecycleRules} from './lifecycle-view.mjs';
import {scenarioExplanation,resetSummary,thesisLabel} from './scenario-view.mjs';
import {comparisonAt,comparisonDay} from './comparison.mjs';
import {DEMO_REFERENCE} from './demo-reference.mjs';
import {getLanguage} from './locales/locale.mjs';
import {simulate,valuation,pricePosition,CASES,CAPITAL,BASE} from './long-term.mjs';
import {chart,priceBand,eventTable} from './lab.mjs';
import {valuationShift} from './revision-view.mjs';
import {feeControls,feeContributionTable} from './fee-view.mjs';
import {nextMilestone,feeDecisionBridge} from './journey-view.mjs';
import {factorBridge} from './research-view.mjs';
import {valuationZones,valuationPaint} from './valuation-visual.mjs';

const t=(zh,en)=>getLanguage()==='en'?en:zh;
const money=(v,d=0)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:d}).format(v);
const signed=(v,d=0)=>(v>=0?'+':'−')+money(Math.abs(v),d);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tone=v=>v>=0?'positive':'negative';
const time=day=>day===0?t('起点','Start'):t(`${Math.floor(day/365)} 年 ${Math.floor(day%365/365*12)} 个月`,`${Math.floor(day/365)}y ${Math.floor(day%365/365*12)}m`);
const span=r=>money(r[0],2)+'–'+money(r[1],2);
const COLORS=['#344cec','#008b7c','#9caedd','#baa16d'];
const roles=()=>['Core LP','Active LP',t('钱包持股','Wallet shares'),t('钱包现金与费用','Wallet cash & fees')];
const btn=(attr,label,primary=false)=>`<button class="${primary?'primary':'text-button'}" ${attr}>${label}</button>`;
const metric=(label,value,note='',cls='')=>`<div class="metric"><span>${label}</span><strong class="${cls}">${value}</strong><small>${note}</small></div>`;
const head=(tag,title,sub='')=>`<header class="flow-heading"><div class="eyebrow">${tag}</div><h1 tabindex="-1">${title.replace(/[。.]$/,'')}</h1>${sub?`<p>${sub}</p>`:''}</header>`;
export const FLOW_ROUTES=['simulate','revise','result'];
export function flowSteps(view){const names=t(['策略表现','AI 修正','比较结果'],['Performance','AI revision','Compare']);return `<nav class="flow-steps" aria-label="${t('体验步骤','Walkthrough steps')}">${FLOW_ROUTES.map((v,i)=>`<button data-go="${v}" ${view===v?'aria-current="step"':''}><span>${String(i+1).padStart(2,'0')}</span>${names[i]}</button>`).join('')}</nav>`;}

const footer=()=>`<p class="flow-foot">${t('构造情景 · 无杠杆、零摩擦成本 · 可跑输持股','Constructed scenarios · No leverage or friction costs · May underperform shares')}</p>`;
function endAction(back,attr,label){return `<div class="flow-next">${back?btn(`data-go="${back}"`,t('← 上一步','← Back')):'<span></span>'}${btn(attr,label+' →',true)}</div>`;}

function allocation(p,compare=false,showNote=true){const values=[p.sleeves[0],p.sleeves[1],p.sleeves[2],p.sleeves[3]+p.feeCash];return `<div class="flow-allocation"><div class="allocation-bar" role="img" aria-label="${roles().map((r,i)=>r+' '+(values[i]/p.nav*100).toFixed(1)+'%').join(', ')}">${values.map((v,i)=>`<span style="width:${v/p.nav*100}%;background:${COLORS[i]}"></span>`).join('')}</div><div class="flow-allocation-key">${roles().map((name,i)=>`<div><span><i style="background:${COLORS[i]}"></i>${name}</span><b>${(values[i]/p.nav*100).toFixed(1)}%</b>${compare?'':`<small>${money(values[i])}</small>`}</div>`).join('')}</div>${showNote?`<small>${t('按总资产计算；已关闭 LP 的资产归入钱包，现金包含费用留现','Based on total assets; closed LP assets move to the wallet, and cash includes retained fees')}</small>`:''}</div>`;}
const feeStrip=(s,draft=false)=>`<div class="flow-assumptions"><span>${t('LP 费用假设','LP fee assumptions')} · Core ${s.coreApr}% · ${t('Core 积累','Core accumulation')} ${s.buyApr}% / Active ${s.activeApr}% APR</span>${btn(`data-detail="settings" ${draft?'data-detail-draft':''}`,t('交易与费用设置','Trading & fee settings'))}</div><div class="flow-toggles"><label><input type="checkbox" ${draft?'data-draft':'data-input'}="reinvest" ${s.reinvest?'checked':''}> ${t('手续费按年复投','Reinvest fees annually')}</label><small>${t('仅区间内计费 · 手续费已计入资产','In-range capital only · Fees included in assets')}</small></div>`;
const series=(r,old,revised)=>[{points:r.points,key:'nav',name:revised?t('调整后策略','Revised strategy'):t('估值不变策略','Original-valuation strategy'),color:COLORS[0]},...(revised?[{points:old.points,key:'nav',name:t('估值不变策略','Original-valuation strategy'),color:'#ad8bc3',dash:true}]:[]),{points:r.points,key:'pure',name:t('纯持股','Buy-and-hold shares'),color:'#919db2'},...(!revised?[{points:r.points,key:'usdc',name:t('初始本金','Starting capital'),color:'#baa16d',dash:true,baseline:true}]:[])];

export function createFlow({state,draft,data,historyData,research,feeReference,documents,ui,lab,archiveEvidence,liveEvidence=null,feeObservation=null}){
  const argumentsHistory=historyData;
  const s=()=>state;
  function home(){
    const steps=[
      [t('先判断公司价值','Start with company value'),t('用财务数据建立悲观、中性、乐观三种估值，为何时偏向持股、何时逐步兑现提供依据。','Build bear, base and bull valuations from financial data: a basis for deciding when to hold shares or take profit.')],
      [t('再用 AI 安排持仓','Let AI propose the strategy'),t('结合估值、技术指标与持有目标，提出 LP 区间，以及股票和现金的安排。','Combine valuation, technical indicators and holding objectives to propose LP ranges and a mix of shares and cash.')],
      [t('随价格运行，随公司修正','Manage price moves. Review company changes.'),t('在有效区间内逐步换仓并赚取手续费；持续跟踪新闻与财报，必要时重估并调整策略。','Earn fees as inventory changes within active ranges. Track news and filings, then revalue and adjust when the evidence warrants it.')]
    ];
    return `<section class="flow-hero balanced-hero"><div class="eyebrow">VALUERANGE / SOLANA</div><h1 tabindex="-1">${t('<span>用 AI，把公司估值</span> <span class="hero-accent">变成链上 LP 策略</span>','<span>Use AI to turn company value</span> <span class="hero-accent">into on-chain LP strategies</span>')}</h1><p>${t('以公司价值为依据，在持股、提供流动性（LP）与保留现金之间做选择。','Use company value to decide when to hold shares, provide liquidity (LP) or keep cash.')}</p><div class="intro-context"><span>CIRCLE / CRCLx</span><span>Raydium LP</span><span>${t('长期策略案例','A long-term strategy case')}</span></div></section>
    <section class="panel strategy-intro"><div class="row"><h2>${t('这套策略怎样工作','How the strategy works')}</h2><span class="subtle-label">${t('估值 → 决策 → 持续管理','Value → Decide → Manage')}</span></div><ol class="explain-steps">${steps.map(([title,body],i)=>`<li><span class="step-number">0${i+1}</span><div><h3>${title.replace(/[。.]$/,'')}</h3><p>${body}</p></div></li>`).join('')}</ol><div class="strategy-roles">${[[t('Core LP','Core LP'),t('宽区间管理库存','Broad inventory range')],['Active LP',t('分段积累或兑现','Accumulate or take profit')],[t('持股 + 现金','Shares + cash'),t('参与上涨，保留余地','Upside exposure and flexibility')]].map(([title,body])=>`<div><b>${title}</b><span>${body}</span></div>`).join('')}</div></section>
    <div class="strategy-summary"><p>${t('希望把价格波动转为换仓机会与手续费，同时保留长期持股的空间。','The aim: turn price swings into inventory opportunities and fees while retaining long-term share exposure.')}</p><span>${t('取舍：LP 会逐步卖出股票，持续上涨时可能跑输持股；估值也可能判断错误。','The trade-off: LPs sell shares as prices rise and may lag a sustained rally. Valuations can also be wrong.')}</span>${btn('data-detail="guide"',t('策略规则与风险','Strategy rules & risks')+' ↗')}</div>
    <div class="strategy-start"><div class="case-intro"><span class="eyebrow">CASE 01 / CIRCLE</span><h2>${t('先用 CIRCLE，体验完整策略','Explore the method with CIRCLE')}</h2><p>${t('本次以 USDC 发行方 Circle（CRCL）为例，连接已有研究与运行记录。同一方法可扩展至其他公司，先为每家公司建立财务底稿、估值模型与跟踪规则。','This demo uses Circle (CRCL), the issuer of USDC, with existing research and operating records. The method can extend to other companies after building their financial inputs, valuation models and monitoring rules.')}</p></div>${btn('data-flow-start',t('体验 CIRCLE 策略','Try the CIRCLE strategy')+' →',true)}<p>${t('体验模拟 → 查看真实实盘 → 理解 AI 与策略','Try the simulation → See live evidence → Explore AI & strategy')}</p><small>${t('预设案例 · 模拟操作 · 无需连接钱包','Prepared case · Simulated actions · No wallet needed')}</small></div>`;
  }
  function plan(){return library();}
  function strategyPrinciples(){
    const p=simulate({...state,revision:'unchanged'}).points[0];
    return `<section class="panel flow-main-panel plan-value"><div class="valuation-origin"><div class="plan-stage-heading"><span class="step-number">01</span><h2>${t('先看公司值多少，再看价格在哪里','Value the company, then locate the price')}</h2></div><p>${t('以 Circle 的财报与经营数据为基础，AI 与金融 Skill 整理不同经营假设，再由估值模型算出悲观、中性、乐观三个区间。','Using Circle’s filings and operating data, AI and financial Skills organize the business assumptions. The valuation model then calculates Bear, Base and Bull ranges.')}</p>${valuationModelRoute()}<p class="principle-roles">${t('取数：财报、电话会议与经营数据 → 带日期的财务底稿。Skill 规定口径，AI 组织假设，公式计算估值边界。','Data: filings, earnings calls and operating data → dated financial inputs. Skills define conventions, AI organizes assumptions, and formulas calculate valuation boundaries.')}</p><div class="flow-doc-links">${btn('data-doc="valuation_inputs"',t('查看财务底稿','View financial inputs')+' ↗')}</div></div>
    <div class="case-reference"><div><span>${t('示例起点 · CRCL 美股收盘价','Case start · CRCL market close')}</span><b>${DEMO_REFERENCE.sessionDate} <strong>${money(p.price,2)}</strong></b></div><p>${t('用这一天的真实收盘价作为案例起点，先与公司价值作对照。','This recorded closing price is the case starting point. First, compare it with company value.')}</p></div>
    ${planValuation(p.price)}<div class="plan-price-reading"><span>${t('价格定位','Price position')}</span><p>${t('这一起点位于乐观区间下部，意味着价格已包含一定增长预期。它为后续仓位提供参照，不直接决定 LP 的上下沿。','The starting price sits in the lower Bull range, reflecting some growth expectations. This informs the allocation; it does not directly set the LP boundaries.')}</p></div><div class="plan-why-link">${btn('data-detail="foundation"',t('查看估值的数据、假设与计算方法','Explore the valuation data, assumptions & calculation')+' ↗')}</div></section>
    <div class="plan-ai-bridge" aria-label="${t('从估值到持仓','From valuation to allocation')}"><span>${t('估值给出参照','Valuation provides context')}</span><i>↓</i><span>${t('AI 再结合技术面、现有持仓与目标','AI adds technicals, existing holdings and objectives')}</span></div>
    <section class="panel plan-allocation"><div class="plan-stage-heading"><span class="step-number">02</span><h2>${t('由 AI 把估值转成区间与仓位','Let AI turn valuation into ranges and positions')}</h2></div><p class="plan-allocation-intro">${t('先确定在哪些价格区间逐步换仓，再决定分配多少资金；保留部分持股参与上涨，保留现金等待机会。','Choose where to convert inventory, then how much capital to allocate. Retain some shares for upside and cash for later opportunities.')}</p><div class="plan-archive-label">${t('沿用 2026.08.24 历史 AI 提案的区间与比例','Ranges and weights from the archived AI proposal · 2026.08.24')}</div><p class="principle-roles">${t('输入：已确认估值、技术资料、现有库存与持有目标。AI 在 Skill 约束下提出候选；程序核对资金与股票数量，实际操作另需批准与确认。','Inputs: confirmed valuation, technical data, inventory and holding objectives. Under Skill-defined constraints, AI proposes candidates; code checks cash and share quantities. Execution requires separate approval and confirmation.')}</p>${planRanges(p.price)}<div class="plan-capital-heading"><h3>${t('再配资金：$10,000 如何分工','Then allocate: how the $10,000 is divided')}</h3><p>${t('按 $92.02 重建模拟起始数量；区间和比例沿用历史提案。','Starting quantities are recalculated at $92.02; ranges and weights retain the historical proposal.')}</p></div>${allocation(p,false,false)}<div class="plan-why-link">${btn('data-detail="plan"',t('AI 为什么选这些区间与资金比例？','Why did AI choose these ranges and weights?')+' ↗')}${btn('data-doc="ai_decision"',t('查看历史 AI 提案','View the archived AI proposal')+' ↗')}</div></section>`;
  }
  function runControls(){return `<details class="performance-assumptions" id="performance-assumptions" ${ui.assumptionsOpen?'open':''}><summary>${t('行情与模拟假设','Market path & simulation assumptions')}</summary><div class="assumptions-body"><h3>${t('5 年 · 波动上涨','5 years · Rally with pullbacks')}</h3><p>${t('构造行情用于解释策略表现，目标价与费用均为模拟假设。','A constructed market path explains strategy behavior. Target prices and fees are simulation assumptions.')}</p><div id="market-path-preview">${pathPreview(state)}</div>${details('settings')}</div></details>`;}

  function targetControls(){return `<section class="target-settings"><h3>${t('原始情景的到期目标价','Ending target for the original scenario')}</h3><label for="end-number">${state.years} ${t('年后','years')} · USD</label><input id="end-number" type="number" min="1" max="400" step="1" value="${state.end}" data-input="end"><p class="flow-caption">${t('这里设置事件发生前的原始情景；AI 修正页会在此基础上衔接事件后的行情。','This sets the original scenario. AI revision derives the post-event market from it.')}</p><div id="end-position" class="valuation-price-zones">${endingTag()}</div><div class="valuation-slider"><input id="end" data-input="end" type="range" min="1" max="400" step="1" value="${state.end}" aria-label="${t('到期目标价','Ending target')}" style="--valuation-gradient:${valuationPaint(state.end,'unchanged').gradient};--price-ink:${valuationPaint(state.end,'unchanged').color}"></div><div class="valuation-scale"><span>$1</span><span>$400</span></div></section>`;}
  function endingTag(){const pos=pricePosition(state.end,'unchanged'),paint=valuationPaint(state.end,'unchanged');return valuationZones(state.end,'unchanged',{interactive:true})+`<div class="valuation-price-status" style="--price-ink:${paint.color}"><span>${pos.label}</span><small>${pos.description}</small>${btn('data-detail="price"',t('这个价格处于什么估值水平？','Where does this price sit in the valuation?')+' ↗')}</div>`;}
  function runResult(){
    const r=simulate({...state,revision:'unchanged'}),p=r.points[state.day];
    return `<section class="panel flow-chart compact-portfolio"><div class="row"><h2>${t('资产与仓位，一起看','Assets and holdings together')}</h2><small>${t('估值不变策略 · 对比纯持股','Original valuation · vs buy-and-hold')}</small></div>
    <div class="metrics-grid">${metric(t('当前模拟资产','Simulated assets'),money(p.nav))}${metric(t('相对持股收益差','Return difference vs shares'),signed(p.nav-p.pure),((p.nav-p.pure)>=0?'+':'−')+(Math.abs(p.nav-p.pure)/CAPITAL*100).toFixed(2)+t(' 个百分点',' pp'),tone(p.nav-p.pure))}${metric(t('累计手续费','Fees earned'),money(p.fees),t('已计入资产','Included in assets'),'positive')}</div>
    <div id="run-chart-content">${chart(series(r,r,false),{cursor:state.day,compact:true})}</div>
    <div class="flow-time"><div class="observation-head"><label for="day">${t('观察时点','Observation time')} <output id="day-label">${time(state.day)}</output></label><p id="observation-price" class="observation-price">${t('股价','Share price')} ${money(p.price,2)} · ${t(['极端折价','悲观区间','中性区间','乐观区间','极端溢价'],['Extreme discount','Bear range','Base range','Bull range','Extreme premium'])[pricePosition(p.price,'unchanged').index]}</p></div>
    <input id="day" data-input="day" type="range" min="0" max="${state.years*365}" value="${state.day}" aria-label="${t('观察时点','Observation time')}"><div class="flow-time-actions">${btn('data-observe="0"',t('起点','Start'))}${btn(`data-next-event data-observe="${nextMilestone({...state,revision:'unchanged'})}"`,t('下一事件','Next event')+' →')}${btn(`data-observe="${reviewDay(state.eventYear)}"`,state.eventYear<1?t('第 6 个月复核','Month 6 review'):t(`第 ${state.eventYear} 年复核`, `Year ${state.eventYear} review`))}${btn(`data-observe="${state.years*365}"`,t('期末','End'))}</div></div>
    ${runControls()}${investmentInline(r,state.day)}${compactHoldings(p)}</section>`;
  }
  function run(){return head('01 / PERFORMANCE',t('策略表现','Strategy performance'),t(`模拟表现 · 五年波动上涨 · 基准本金 $10,000 · 起价 ${money(state.startPrice,2)}`,`Simulated performance · Five-year rally with pullbacks · $10,000 reference capital · ${money(state.startPrice,2)} opening price`))+`<div id="simulation-results">${runResult()}</div>`+endAction(null,'data-review',t('下一步：看 AI 如何修正','Next: explore AI revision'))+footer();}

  function reviewResult(){const r=simulate(eventScenario(state)),before=r.reviewSnapshot,after=r.revisionSnapshot,key=draft.revision;return `<section class="panel flow-review-controls"><div class="row"><h2>${t('选择发生的事件','Choose an event')}</h2><label class="flow-select">${t('发生时间','Event time')} <select data-draft="eventYear" aria-label="${t('事件发生时间','Event time')}">${reviewYears(state.years).map(v=>`<option value="${v}" ${v===state.eventYear?'selected':''}>${reviewLabel(v,getLanguage())}</option>`).join('')}</select></label></div><div class="flow-choices company-choices">${[['improve',t('突发利好','Positive news'),'↗'],['unchanged',t('不变','No change'),'→'],['pressure',t('突发利空','Negative news'),'↘']].map(([v,label,icon])=>`<button data-story="${v}" aria-pressed="${key===v}"><span>${icon}</span><b>${label}</b></button>`).join('')}</div><p class="flow-context">${t('选择后立即展示估值与仓位修正，同时衔接事件后的模拟走势。','Selections immediately update valuation, allocation and the simulated post-event market.')}</p><div class="event-outcome"><span>${t('本次修正','Revision')}</span><strong>${thesisLabel(key)}</strong></div><div class="flow-review-seed"><span>${t('事件后的模拟到期价','Simulated ending price after the event')} <b>${money(r.options.end)}</b></span><small>${t('事件前行情保留','Pre-event prices preserved')}</small></div><p class="flow-caption">${t('这是预设事件演示：后续价格也是模拟设定，不表示现实中的利好必然推动股价上涨。','A prepared event demonstration: subsequent prices are assumptions, not a claim that positive news must raise market prices.')}</p></section><section class="panel flow-change"><div class="row"><h2>${thesisLabel(key)}</h2>${btn('data-detail="factors" data-detail-draft',t('估值为什么改变？','Why did the valuation change?')+' ↗')}</div>${valuationShift(key,before.price)}<div class="flow-transition"><span>${t('估值更新','Revised valuation')}</span><i>↓</i><span>${t('AI 重新安排持仓','AI revises the allocation')}</span></div><div class="flow-compare-allocation"><section><h3>${t('调整前','Before')}</h3>${allocation(before,true)}</section><section><h3>${t('调整后','After revision')}</h3>${allocation(after,true)}</section></div><div class="flow-lp-changes"><div><span>Core LP</span><b>${before.coreLiquidity>0?span(before.coreRange):t('已关闭','Closed')} → ${after.coreLiquidity>0?span(after.coreRange):t('关闭','Closed')}</b></div><div><span>Active LP</span><b>${key==='unchanged'?t('沿用原区间与规则','Keep original ranges and rules'):t('关闭旧区间','Close the old range')}</b></div></div><p class="flow-decision">${key==='improve'?t('暂停 Active LP，按增长配置安排股票，并上移 Core LP。','Pause Active LP, apply the growth allocation and move Core LP higher.'):key==='pressure'?t('关闭旧 LP，股票最多保留本金的 10%；已有持股更少就不补买。','Close old LPs and cap shares at 10% of principal; never buy up to that cap.'):t('保留原区间，继续分批兑现与积累。','Keep the ranges; continue staged distribution and accumulation.')}</p><div class="review-fee-status"><span>${t('调整后，此刻能收手续费的仓位','Positions earning fees just after the change')}</span><b>${[['core','Core LP'],['active','Active LP']].filter(([role])=>after.feeRunRates[role]>0).map(([,label])=>label).join(' + ')||t('暂无 LP 处于有效区间','No LP is currently in range')}</b></div><p class="flow-caption">${t('调仓当下不增加资产。后续股价、持仓与手续费的共同结果，在下一步比较。','Rebalancing itself adds no assets. The next step compares the combined effect of later prices, holdings and fees.')}</p>${btn('data-detail="reviewReason" data-detail-draft',t('为什么这样调仓，手续费会怎样变化？','Why rebalance, and what happens to fees?')+' ↗')}</section><div class="flow-next">${btn('data-go="simulate"',t('← 返回策略表现','← Back to performance'))}${btn('data-go="result"',t('查看比较结果','Compare results')+' →',true)}</div>`;}
  function review(){return head('02 / AI REVISION',t('如果出现新的公司事实，AI 会怎样调整？','New company facts. How would AI adjust?'),t('预设事实变化 → 估值修正 → 仓位调整','Prepared event → Revised valuation → Updated allocation'))+`<div id="revision-results">${reviewResult()}</div><section class="panel tracking-foundation"><div class="row"><h2>${t('AI 持续跟踪公司，也持续复核持仓','AI monitors the company and reviews the positions')}</h2><small>${t('已收录研究','Archived research')} · ${esc(research.latestDate)}</small></div><div class="tracking-columns">${[[t('跟踪变化','Track changes'),t('新闻、财报、公开披露的内部人交易，以及经营与价格变化。','News, filings, publicly disclosed insider trades, and business and market changes.')],[t('结合现有仓位','Review the portfolio'),t('对照公司估值、Core / Active LP 区间、股票和现金配置，检查原判断是否仍成立。','Review valuation, Core / Active LP ranges, shares and cash against the original thesis.')],[t('形成后续建议','Propose next steps'),t('继续观察、建议复核估值，或提出仓位与 LP 调整建议，并保留依据。','Continue monitoring, recommend a valuation review or propose position and LP changes, with supporting evidence.')]].map(([h,p])=>`<div><h3>${h}</h3><p>${p}</p></div>`).join('')}</div><p class="flow-caption">${t('这里说明后台研究工作流的跟踪范围，已有记录可供核对；本页使用预设方案演示，不代表正在实时调用 AI。','This describes the research workflow and its monitoring scope. Archived records are available; this page demonstrates prepared decisions, without a live AI call.')}</p>${btn('data-detail="research"',t('查看跟踪记录与建议','View monitoring records & recommendations')+' ↗')}</section>`+footer();}
  function resultDay(){return comparisonDay(ui.comparisonDay,state.years*365);}
  function comparisonSnapshot(){const effective=eventScenario(state),r=simulate(effective),old=simulate({...effective,revision:'unchanged'});return comparisonAt(r,old,resultDay());}
  function resultPanels(){
    const effective=eventScenario(state),r=simulate(effective),old=simulate({...effective,revision:'unchanged'}),q=comparisonAt(r,old,resultDay()),p=q.point,base=q.original,revised=state.revision!=='unchanged';
    const phase={unchanged:t('估值保持不变','Valuation unchanged'),before:t('尚未调整 · 两套策略一致','Before review · Strategies match'),review:t('调整时点 · 换仓不凭空增加资产','At review · Rebalancing creates no extra assets'),after:t('调整后 · 观察差额演变','After review · Track the difference')}[q.phase];
    const roi=x=>t(`累计 ROI ${x.toFixed(1)}%`,`Cumulative ROI ${x.toFixed(1)}%`);
    let explanation=t('比较的是同一时点、同一价格路径下的资产差额，不是额外到账的现金。','This compares asset values at the same time and on the same price path, not additional cash received.');
    if(q.phase==='before'||q.phase==='review')explanation=t('调整尚未产生后续收益，向后移动时间观察差额如何出现。','The decision has not produced subsequent returns yet. Move forward to see the difference develop.');
    else if(q.totalDelta>0&&q.feeDelta<0)explanation=t('手续费少了一些，但持仓与再部署带来的增益更大，因此总资产仍然更高。','Lower fee income is more than offset by gains from holdings and redeployment, so total assets are higher.');
    else if(q.totalDelta<0&&q.feeDelta>0)explanation=t('手续费增加了，但没有抵消持仓与再部署的损益差额，因此总资产仍然更低。','Higher fee income does not offset the holdings and redeployment difference, so total assets are lower.');
    return `<div id="comparison-summary"><div class="comparison-observation"><span>${t('观察时点','Observation time')} <b>${time(q.day)}</b></span><span>${t('此刻股价','Share price now')} <b>${money(p.price,2)}</b></span><small>${phase}</small></div><div class="metrics-grid flow-result-metrics">${metric(t('调整方案资产','Revised-plan assets'),money(p.nav),roi(p.roiPct))}${metric(t('估值不变策略','Original-valuation strategy'),money(base.nav),roi(base.roiPct))}${metric(t('纯持股','Buy-and-hold shares'),money(p.pure),roi((p.pure/CAPITAL-1)*100))}</div></div>
    <section class="panel comparison-chart"><div id="comparison-chart-content">${chart(series(r,old,revised),{cursor:q.day,eventDay:revised?r.eventDay:null})}</div><div class="flow-time"><label for="compare-day">${t('观察时点','Observation time')} <output id="compare-day-label">${time(q.day)}</output></label><input id="compare-day" data-comparison-day type="range" min="0" max="${state.years*365}" step="1" value="${q.day}" aria-label="${t('比较观察时点','Comparison observation time')}"><div class="flow-time-actions">${btn('data-comparison-observe="0"',t('起点','Start'))}${btn(`data-comparison-observe="${r.eventDay}"`,t('调整时点','Review point'))}${btn(`data-comparison-next data-comparison-observe="${Math.min(q.day+92,state.years*365)}"`,t('向后 3 个月','Forward 3 months'))}${btn(`data-comparison-observe="${state.years*365}"`,t('期末','End'))}</div><p class="flow-caption">${t('灰色游标跟随观察时间；紫色虚线固定标出调整日期。拖动会同步更新资产、手续费与差额。','The gray cursor follows observation time; the purple dashed line marks the fixed review date. Scrubbing updates assets, fees and differences together.')}</p></div></section>
    <section id="comparison-attribution" class="panel comparison-attribution"><div class="comparison-total"><div><h2>${t('调整后，资产多了还是少了？','Did the change leave you with more or less?')}</h2><small>${t('相对同一时点的估值不变策略','Versus the original-valuation strategy at the same time')}</small></div><strong class="${tone(q.totalDelta)}">${signed(q.display.totalDelta,2)}</strong></div><div class="comparison-parts"><div><span>${t('持股与区间操作的差额','Difference from holdings & range decisions')}</span><strong class="${tone(q.positionDelta)}">${signed(q.display.positionDelta,2)}</strong><small>${t('包括股票涨跌、LP 换仓和手续费复投后的涨跌','Includes share prices, LP inventory changes and gains/losses after fee reinvestment')}</small></div><b class="comparison-plus" aria-hidden="true">+</b><div><span>${t('多收或少收的手续费','Extra or forgone fees')}</span><strong class="${tone(q.feeDelta)}">${signed(q.display.feeDelta,2)}</strong><small>${t('仅手续费这一项，不是总收益差额','Fee income only, not the total return difference')}</small></div></div><p class="comparison-explanation">${explanation}</p><div class="comparison-fee-totals"><span>${t('累计手续费','Cumulative fees')}</span><b>${t('调整方案','Revised plan')} ${money(p.fees,2)}</b><b>${t('估值不变','Original valuation')} ${money(base.fees,2)}</b><small>${t('分别已计入两套方案的资产，不能再次相加','Already included in each portfolio; do not add again')}</small></div>${scenarioExplanation(r,old,q)}<div class="comparison-detail-link">${btn('data-detail="returns"',t('查看完整归因','View full attribution')+' ↗')}</div></section>`;
  }
  function result(){const effective=eventScenario(state),event=t({improve:'突发利好',unchanged:'不变',pressure:'突发利空'},{improve:'Positive news',unchanged:'No change',pressure:'Negative news'})[state.revision];return head('03 / COMPARE',t('这次调整，改变了什么？','What did the decision change?'),t('相同 $10,000 起点与价格路径','Same $10,000 start and price path'))+`<p class="result-readonly">${state.years} ${t('年模拟','year simulation')} · ${reviewLabel(state.eventYear,getLanguage())} · ${event} · ${t('到期价','Ending price')} ${money(effective.end)}</p><div id="comparison-results">${resultPanels()}</div><div class="flow-result-tools">${btn('data-review',t('返回 AI 修正','Back to AI revision'))}${btn('data-go="simulate"',t('返回策略表现','Back to performance'))}</div>`+endAction('revise','data-go="evidence"',t('查看真实实盘','See the live evidence'))+footer();}
  function evidence(){
    const historyData=liveEvidence?.history??argumentsHistory;
    const d=liveEvidence?.case??data,p=d.pnl,last=historyData.nav.at(-1),first=historyData.nav[0];
    const fees=historyData.feeHistory,period=fees.start.slice(0,10)+' → '+fees.end.slice(0,10);
    return head('LIVE / CIRCLE',t('真实仓位，持续验证','Real positions, ongoing validation'),t('正式历史快照','Official historical snapshot')+' · '+d.snapshotAt)+liveStatus(liveEvidence)+
    `<p class="page-intro">${t('观察相对持股表现、持续产生的手续费，以及链上实际持仓。','Track performance versus shares, fees earned and the positions held on-chain.')}</p>
    <div class="metrics-grid live-metrics">${metric(t('相对纯 CRCLx 的超额','Excess vs pure CRCLx'),signed(p.excessPure,2),first.date.slice(0,10)+' → '+last.date.slice(0,10),tone(p.excessPure))}${metric(t('期间累计手续费估值','Cumulative marked fee value'),money(fees.total,2),period,'positive')}${metric(t('当前组合净值','Current portfolio NAV'),money(d.nav.totalUsd,2),t('股票、现金与待领取费用','Shares, cash and unclaimed fees'))}</div>
    <p class="metric-context">${t('超额表示相对持股的差额；手续费是收益的一部分，均不等于组合总盈利。','Excess is the difference versus holding shares. Fees are one return component; neither is total portfolio profit.')}${btn('data-detail="live"',t('完整盈亏与口径','Full P&L and methodology')+' ↗')}</p>
    ${feeObservationPanel(feeObservation,d.snapshotAt)}
    <section class="panel live-strategy-explanation"><div class="row"><h2>${t('同一只股票，让收益来自三部分','One stock. Three sources of return')}</h2><small>${t('策略目标','Strategy objective')}</small></div><p>${t('这套策略优化的是选股后的持仓方式：在同一只股票上，用估值安排股票、LP 和现金，争取比单纯持股获得更好的综合结果。','This strategy optimizes how you hold a stock after choosing the company. Valuation guides shares, LPs and cash, aiming for a better combined result than holding the same stock alone.')}</p><div class="return-sources"><span>${t('持股涨跌','Share price exposure')}</span><i>+</i><span>${t('LP 手续费','LP fees')}</span><i>+</i><span>${t('分批买卖的波段结果','Staged buying and selling')}</span></div><p>${t('上涨时，LP 会逐步卖出股票，可能少赚部分涨幅；策略希望用手续费和波段操作弥补这部分差距。股票与现金的切换，也减少了对始终满仓持股的依赖。','LPs gradually sell shares as prices rise and may miss some upside. Fees and staged trades aim to make up that gap. Moving between shares and cash also reduces reliance on staying fully invested at all times.')}</p><small class="live-strategy-validation">${t('持续记录持股、波段与手续费的贡献，复核偏差、改进规则；能否跑赢，仍要靠不同市场下的实盘验证。','Track contributions from shares, staged trades and fees, review discrepancies and refine the rules. Outperformance still needs live validation across different markets.')}</small></section>
    <section class="panel"><div class="row"><h2>${t('净值对比','Recorded NAV')}</h2><small>${period} · ${t('起点 = 100','Start = 100')}</small></div>${chart([{points:historyData.nav,key:'nav',name:t('实盘策略','Live strategy'),color:COLORS[0]},{points:historyData.nav,key:'pure',name:t('纯 CRCLx','Pure CRCLx'),color:'#919db2'},{points:historyData.nav,key:'usdc',name:t('初始本金','Starting capital'),color:'#baa16d',dash:true}],{calendar:true,indexed:true})}<p class="flow-caption">${t('正式记录；期间存在取价口径变化，非完整审计收益。','Official records span valuation-method changes; not fully audited returns.')}</p></section>
    ${feeHistoryPanel(fees)}
    <section class="panel"><div class="row"><h2>${t('查看链上持仓','Verify the on-chain positions')}</h2><small>Solana / Raydium</small></div><div class="flow-live-positions">${[...d.positions].sort((a,b)=>a.role===b.role?0:a.role==='Core'?-1:1).map(x=>`<a href="https://solscan.io/account/${x.positionPda}" target="_blank" rel="noopener noreferrer"><span>${x.role} LP ↗<small>${span([x.rangeLowerUsdcPerCrclx,x.rangeUpperUsdcPerCrclx])}</small></span><b>${money(x.totalUsd)}<small>${x.crclxQty.toFixed(2)} CRCLx + ${money(x.usdcQty)} USDC</small></b></a>`).join('')}<div><span>${t('独立持股与储备','Direct shares & reserve')}<small>${d.wallet.pureCrclxQty.toFixed(2)} CRCLx</small></span><b>${money(d.wallet.pureCrclxUsd+d.wallet.jlusdcUsd+(d.wallet.usdcUsd??0))}</b></div></div><p class="flow-caption">${t('点击 LP 查看链上账户；上方金额为标注时点的快照。','Open an LP to inspect its on-chain account. Amounts above are from the dated snapshot.')}</p></section>
    <div class="flow-link-row">${btn('data-proof="runs"',t('查看运行记录','View run records')+' ↗')}${liveEvidence?btn('data-detail="live"',t('核对本次数据与盈亏','Review this update’s data & P&L')+' ↗'):btn('data-doc="pnl_latest"',t('核对原始报表','Read the P&L report')+' ↗')}</div><div class="live-research-next"><div><b>${t('这些策略判断，来自哪里？','What supports these strategy decisions?')}</b><p>${t('继续了解财务研究、AI 提案与持续跟踪。','Explore the financial research, AI proposals and ongoing monitoring.')}</p></div>${btn('data-go="library"',t('了解 AI 与策略原理','Explore AI & strategy')+' →','primary')}</div>`;
  }
  function library(){
    return head('STRATEGY / VALUERANGE',t('策略介绍','How the strategy works'),t('以 CIRCLE 为例 · 估值 → 配仓 → AI 修正 → 记录与迭代','The CIRCLE case · Valuation → Allocation → AI revision → Records & iteration'))+
    `<section class="panel strategy-overview"><h2>${t('用 AI，把基本面研究转化为流动性区间','Use AI to turn fundamental research into liquidity ranges')}</h2><p>${t('先理解公司值多少，再决定在哪些价格提供流动性、持有股票或保留现金。AI 提出方案，程序按规则管理与核算。','Understand what a company is worth, then decide at which prices to provide liquidity, hold shares or keep cash. AI proposes the strategy; code manages and calculates under defined rules.')}</p></section>`+strategyPrinciples()+`<details class="strategy-system"><summary>${t('系统如何运行','How the system runs')}</summary><section class="panel system-roles"><div class="row"><h2>${t('AI 负责判断，程序负责核算','AI reasons. Code calculates')}</h2>${btn('data-proof="map"',t('查看系统分工','Inspect system roles')+' ↗')}</div><div class="system-role-grid">${[['Skill',t('定义专业方法与约束','Defines methods and constraints')],['AI',t('提出候选，解释取舍','Proposes candidates and explains trade-offs')],[t('确定性代码','Deterministic code'),t('计算库存、费用与盈亏','Calculates inventory, fees and P&L')],['Harness',t('编排流程，记录版本与状态','Orchestrates runs, versions and status')]].map(([title,body])=>`<div><b>${title}</b><p>${body}</p></div>`).join('')}</div></section></details>`+`
    ${strategyLearning(research.latestDate,(liveEvidence?.case??data).snapshotAt)}
    <div class="live-research-next"><div><b>${t('从 CIRCLE 案例，走向更多用户','From the CIRCLE case to more users')}</b><p>${t('看看这套研究与策略能力，如何成为金库与自托管 Agent。','See how this research and strategy workflow could power Vaults and self-custodial Agents.')}</p></div>${btn('data-go="future"',t('探索未来方向','Explore what’s next')+' →',true)}</div>`;
  }
  function future(){
    const tracks=[
      ['01','VAULT',t('把策略交给金库管理','Let a vault manage the strategy'),t('适合希望简化操作、委托统一策略管理的用户。','For users who want simpler access through a managed strategy.'),t('选择策略与风险范围 → 存入资产 → 查看净值与退出','Choose a strategy and risk limits → Deposit assets → Track NAV and withdraw'),t('扫描可用池子，围绕估值定期复核，再按规则管理 LP、股票与现金；用份额净值与归因持续核算。','Scan eligible pools, review valuations and manage LPs, shares and cash under defined rules, with share NAV and return attribution.'),t('待开发：金库合约、份额与申赎、管理权限、风险控制与审计','To build: vault contracts, shares and withdrawals, management permissions, risk controls and audits')],
      ['02','SELF-CUSTODY AGENT',t('自己掌管资产，让 Agent 协助交易','Keep custody. Let an agent assist'),t('适合希望保留资产控制权、按个人目标管理的用户。','For users who want to retain control and manage to their own objectives.'),t('设定持有目标与权限 → 审阅候选 → 授权执行与持续跟踪','Set objectives and permissions → Review candidates → Authorize execution and monitoring'),t('提供股票、资金与研究资料，建立个性化方案；选择逐笔确认，或让 Agent 在权限内持续跟踪与调仓。','Supply an asset, capital and research to build a personal plan. Confirm each trade yourself, or delegate ongoing monitoring and rebalancing within limits.'),t('待开发：钱包权限、限额与撤销、交易预检、执行反馈','To build: wallet permissions, limits and revocation, transaction preflight and execution feedback')]
    ];
    return head('NEXT / ROADMAP',t('同一套策略，两种未来用法','One strategy foundation. Two ways to use it.'),t('未来产品设想 · 尚未实现','Future product concept · Not yet built'))+
    `<p class="page-intro">${t('把 CIRCLE 已展示的研究与计算流程，逐步变成更多人可以使用的产品。','Develop the research and calculation workflows demonstrated with CIRCLE into products more people can use.')}</p><div class="future-tracks">${tracks.map(([n,tag,title,a,route,b,build])=>`<section class="panel future-track"><div class="future-track-label"><span class="step-number">${n}</span><span class="eyebrow">${tag}</span><span class="badge">${t('规划中','Planned')}</span></div><h2>${title}</h2><p class="future-audience">${a}</p><div class="future-route">${route}</div><p>${b}</p><div class="future-build">${build}</div><div class="concept-card-action">${btn(`data-go="${n==='01'?'vault':'agent'}"`,n==='01'?t('预览 Vault 存入与运行','Preview vault deposits & operations')+' →':t('预览 Agent 策略平台','Preview the Agent strategy platform')+' →','primary')}</div></section>`).join('')}</div>
    <section class="panel future-foundation"><h2>${t('两条路线，共用一个底层','A shared foundation for both')}</h2><p>${t('财务底稿与公司估值 → AI 区间候选 → 持仓监控与复盘','Financial inputs and valuation → AI range candidates → Position monitoring and review')}</p><div class="future-base-note"><b>${t('从一个资产开始，逐步扩展','Start with one asset. Extend carefully.')}</b><span>${t('每接入一家公司，都需要适合它的估值方法、资料与跟踪规则。','Each new company needs a suitable valuation method, source data and monitoring rules.')}</span></div>${btn('data-proof="map"',t('查看已有系统基础','Inspect the existing foundation')+' ↗')}</section><p class="flow-caption">${t('当前 Demo 不接受入金，也不代用户执行交易；自动化产品仍需独立安全与策略验证。','The demo accepts no deposits and executes no user trades. Automated products still need independent security and strategy validation.')}</p>`;
  }
  function details(key,useDraft=false){const o=useDraft?eventScenario(state):state.view==='result'?eventScenario(state):{...state,revision:'unchanged'},r=simulate(o),old=simulate({...o,revision:'unchanged'}),p=state.view==='result'&&!useDraft?r.points[resultDay()]:r.points[o.day];
    if(key==='reviewReason'){
      const before=r.reviewSnapshot,after=r.revisionSnapshot;
      return `<h3>${t('先看持仓变化，再看后续结果','First inspect the allocation, then the later result')}</h3><p>${o.revision==='improve'?t('上调估值后，方案偏向保留股票，暂停旧 Active LP，并把 Core LP 移至新的区间。目的是参与可能的增长，代价是可能少收手续费或错过原区间的波段机会。','A higher valuation favors retaining shares, pauses the old Active LP and moves Core LP to a new range. It seeks growth participation, at the cost of potentially lower fees or fewer opportunities in the original range.'):o.revision==='pressure'?t('下调估值后，先退出旧 LP，减少持股并保留现金，等待新的经营证据。这样可能降低继续下跌时的敞口，也可能错过反弹和手续费。','A lower valuation exits old LPs, reduces shares and keeps cash while waiting for business evidence. This can reduce exposure to further falls, but can also miss rebounds and fees.'):t('估值没有改变，继续沿用原有的持股、换仓与手续费规则。','With valuation unchanged, the original holding, inventory and fee rules continue.')}</p><h3>${t('现在是否有 LP 在收手续费？','Are any LPs earning fees right now?')}</h3><p>${t('只有价格位于有效区间内的 LP 资金才计费。暂停、移出区间或转为持股和现金后，这部分暂不收取新费用；已有手续费仍保留在资产中。','Only LP capital inside its active price range earns fees. Paused or out-of-range LPs, shares and cash earn no new LP fees; fees already earned stay in assets.')}</p><div class="review-rate-detail"><span>${t('按调仓当时的仓位折算一年','One-year equivalent at the rebalance snapshot')}</span><b>${money(before.annualFeeRunRate)} → ${money(after.annualFeeRunRate)}</b></div><p>${t('这只是“当时有效 LP 资金 × 假设 APR”的折算，不是立即到账的收益，也不是全年预测。比较页按整条模拟路径逐段累计手续费，再和持仓涨跌一起计算资产。两处使用同一套计费规则。','This is only in-range capital at that moment × assumed APR, not cash received immediately or a full-year forecast. Compare accrues fees over the simulated path and combines them with portfolio price changes. Both use the same fee rules.')}</p><h3>${t('这次调整的依据来自哪里？','What supports this decision?')}</h3><p>${t('本次交互采用已准备好的 AI 模拟方案，说明估值变化后怎样安排区间与持仓。你可以查看其输入、理由和约束；这里没有重新调用 AI 或执行实盘交易。','This interaction uses a prepared AI scenario explaining how valuation changes affect ranges and holdings. Its inputs, reasoning and constraints are available below. It does not call AI again or execute a live trade.')}</p>${btn('data-proof="candidates"',t('查看 AI 给出的区间与调整理由','See the AI ranges and reasoning')+' ↗')}`;
    }
    if(key==='holdings')return `<p class="flow-caption">${time(p.day)} · ${t('股价','Share price')} ${money(p.price,2)}</p>${currentHoldings(p)}<div class="holding-role-guide"><h3>${t('这些仓位分别做什么？','What do these positions do?')}</h3><p><b>Core LP</b> · ${t('用较宽区间转换股票与现金，符合条件时也承担回落积累。','Converts shares and cash across a broad range; can accumulate on pullbacks when conditions are met.')}</p><p><b>Active LP</b> · ${t('用部分股票分段兑现；退出后保留现金，等待后续条件。','Distributes part of the shares in stages, then retains cash until later conditions are met.')}</p><p>${t('钱包保留直接持股与现金；LP 内部的股币也计入一级页面的股票和现金比例。','The wallet retains direct shares and cash. Assets inside LPs also count toward the share/cash mix shown on the main page.')}</p></div>`;
    if(key==='reset')return resetSummary();
    if(key==='lifecycle'||key==='guide')return lifecycleRules();
    if(key==='settings')return targetControls()+feeControls(o,feeReference,useDraft)+`<div class="strategy-settings"><div class="setting-explanation"><label class="check"><input id="settings-reinvest" type="checkbox" ${useDraft?'data-draft':'data-input'}="reinvest" ${o.reinvest?'checked':''}> ${t('手续费按年复投','Reinvest fees annually')}</label><p>${t('每满一年，把已赚到的手续费追加到对应的区间内 LP；关闭则将手续费留作现金。','At each year-end, add earned fees to the corresponding in-range LP. When off, keep those fees as cash.')}</p></div><div class="setting-explanation"><label class="check"><input id="settings-cycles" type="checkbox" ${useDraft?'data-draft':'data-input'}="cycles" ${o.cycles?'checked':''}> ${t('卖出后，按条件买回并重新开 LP','Buy back and reopen LPs when conditions are met')}</label><p>${t('开启后，卖出所得的可用现金可在回落条件满足时买回股票，回升后再开 LP，参与下一轮。关闭后，现有 LP 达到退出条件就留在钱包，不再按原规则重开。','When on, available sale proceeds can buy shares back at the pullback trigger, then reopen LPs on recovery. When off, existing LPs close at their exit triggers and the assets remain in the wallet without restarting under the original rules.')}</p><small>${t('这个开关控制持仓资金的循环交易；上方开关控制手续费复投。估值修正后按新方案执行。','This controls repeated trading with portfolio funds; the switch above controls fee reinvestment. A valuation revision follows the new plan.')}</small></div></div>${o.revision==='pressure'?`<label class="check"><input type="checkbox" ${useDraft?'data-draft':'data-input'}="recovery" ${o.recovery?'checked':''}> ${t('假设企稳确认后，允许重建 Core LP','Allow Core LP rebuilding after assumed stabilization')}</label><p>${t('仍须满足新中性区间与复核条件；不是自动抄底。','The new Base range and review conditions must also be met; no automatic bottom picking.')}</p>`:''}<p>${t('费率是模拟假设，不等于组合 ROI。仅区间内 LP 资本按时间计费；费用每年检查复投条件。','Rates are simulation assumptions, not portfolio ROI. Only in-range LP capital earns fees; reinvestment eligibility is checked annually.')}</p>`;
    if(key==='price')return priceBand(state.end,'unchanged')+`<p>${t('这里显示你设定的到期目标价处于哪个估值区间。目标价是模拟假设，不代表公司的价格预测或买卖信号。','This shows where your assumed ending target sits within the valuation ranges. It is a simulation input, not a company price forecast or trade signal.')}</p>`;
    if(key==='factors')return factorBridge(draft.revision)+`<div class="table-wrap"><table><thead><tr><th>${t('边界','Boundary')}</th><th>${t('EBITDA','EBITDA')}</th><th>EV / EBITDA</th><th>${t('每股价值','Per-share value')}</th></tr></thead><tbody>${valuation(draft.revision).map((v,i)=>`<tr><td>${i+1}</td><td>${v.ebitda.toFixed(4)}</td><td>${v.multiple.toFixed(2)}</td><td>${money(v.value,2)}</td></tr>`).join('')}</tbody></table></div><p>${t('EBITDA 单位：十亿美元。其余参数沿用底稿；四个边界分别计算。','EBITDA in USD billions. Other inputs retain the source workbook; all four boundaries are recalculated.')}</p>`+btn('data-doc="valuation"',t('查看原估值底稿','Read the valuation workbook')+' ↗');
    if(key==='foundation')return `<div class="foundation-detail"><span class="badge">${t('2026.08.22 估值版本 · 已复制的业务材料','Valuation version 2026.08.22 · Copied business evidence')}</span><h3>${t('先理解 Circle 怎样赚钱','Start with how Circle earns money')}</h3><p>${t('当前主模型把 Circle 视为以储备收益为主的稳定币发行与金融基础设施公司。平均 USDC 规模、储备收益率、分润与经营费用，决定正常化盈利。','The current primary model treats Circle as a stablecoin issuer and financial infrastructure business driven mainly by reserve income. Average USDC supply, reserve yield, distribution economics and operating costs determine normalized earnings.')}</p><div class="foundation-formula"><span>${t('经营因子 → 正常化 Adjusted EBITDA','Operating drivers → Normalized Adjusted EBITDA')}</span><b>${t('每股价值 =（EBITDA × 估值倍数 + 净现金）÷ 稀释股数','Per-share value = (EBITDA × valuation multiple + net cash) ÷ diluted shares')}</b></div><p>${t('在主营逻辑成立时，四组有财务依据的经营假设形成四个边界，并衔接为悲观、中性、乐观三个区间。区间不是股价底线或保证；若公司逻辑改变，需要重新审视模型。','While the core thesis holds, four financially grounded assumption sets produce four boundaries, joined into bear, base and bull ranges. They are not price floors or guarantees; a changed business thesis requires a model review.')}</p><h3>${t('AI 与金融 Skill 具体参与什么','Where AI and financial Skills contribute')}</h3><p>${t('Skill 约束资料口径、估值方法与复核条件；AI 组织研究、提出经营判断与 LP 候选；确定性公式计算价格边界。新闻跟踪负责检查原假设是否仍成立。','Skills define data conventions, valuation methods and review conditions. AI organizes research and proposes business judgments and LP candidates; deterministic formulas calculate the price boundaries. News monitoring checks whether the assumptions still hold.')}</p><div class="flow-doc-links">${btn('data-doc="valuation_inputs"',t('财务数据底稿','Financial inputs')+' ↗')}${btn('data-doc="valuation"',t('完整估值模型','Full valuation model')+' ↗')}${btn('data-proof="map"',t('AI 与 Skill 工作流','AI & Skill workflow')+' ↗')}</div></div>`;
    if(key==='plan')return `<p>${t('本例沿用 2026.08.24 AI 提案的区间与资金比例，按 2026.08.25 收盘价 $92.02 重建模拟股币数量。原始提案与其 $88.53 参考价保持不变。','This case reuses the August 24 AI proposal’s ranges and capital weights, recalculating share/cash quantities at the August 25 close of $92.02. The original proposal and its $88.53 reference are preserved.')}</p><h3>${t('AI 如何选出这两个 LP 区间？','How did AI choose these LP ranges?')}</h3><p>${t('历史提案综合估值、技术面、既有股票与持有目标，保留 $58–172.95 的 Core LP，并用 20% 资金配置 $90–115 的 Active LP，让部分股票随上涨逐步转为现金。','The historical proposal combines valuation, technicals, existing shares and holding objectives. It retains Core LP at $58–172.95 and assigns 20% of capital to Active LP at $90–115, converting part of the shares to cash as prices rise.')}</p>${btn('data-doc="ai_decision"',t('查看 AI 当时的判断与约束','Read the archived AI reasoning and constraints')+' ↗')}<h3>${t('为什么保留四种持仓？','Why use four allocations?')}</h3><ul><li>Core LP：${t('在合理区间转换库存，回落时承担积累；按条件关闭、等待与重启。','Convert inventory in a reasonable range and accumulate on pullbacks; close, wait and restart under defined conditions.')}</li><li>Active LP：${t('分段兑现已有股票，完成后关闭留现。','Distribute existing shares in stages, then close and retain cash.')}</li><li>${t('直接持股：保留长期上涨参与。','Direct shares: retain long-term upside exposure.')}</li><li>${t('现金：保留下一次部署的资金。','Cash: preserve funding for later deployment.')}</li></ul><p>${t('估值提供锚；AI 结合技术面、库存与目标生成区间。原比例是历史配置，不是每日再平衡目标。','Valuation supplies an anchor; AI combines technicals, inventory and objectives to propose ranges. These are historical weights, not daily rebalancing targets.')}</p><p>${t('LP 可能卖早，持股可能继续跌。关闭 LP 不会抹去已产生的无常损失。','LPs may sell too early and shares may keep falling. Closing an LP does not erase existing impermanent loss.')}</p>`+btn('data-doc="valuation"',t('估值怎么算？','How is value calculated?')+' ↗')+btn('data-doc="ai_candidate"',t('历史 AI 提案','Historical AI proposal')+' ↗')+lifecycleRules();
    if(key==='research')return `<div id="research-panel">${lab.researchPanel()}</div>`;
    if(key==='live')return liveEvidence?liveDetails(liveEvidence):archiveEvidence();
    if(key==='returns')return `<h3>${t('当前收益归因','Return attribution')}</h3><p>${time(p.day)} · ${t('相同本金 $10,000','Same $10,000 initial capital')}</p><table><tbody>${[[t('期初组合持有涨跌','Price P&L on initial mix'),p.holdingPnl],[t('静态 LP 无常损失参考','Static LP impermanent-loss reference'),p.il],[t('波段、区间与复投损益','Cycle, range & reinvestment P&L'),p.management],[t('累计手续费','Cumulative fees'),p.fees],[t('总盈亏','Total P&L'),p.nav-CAPITAL]].map(([k,v])=>`<tr><td>${k}</td><td class="${tone(v)}">${signed(v,2)}</td></tr>`).join('')}</tbody></table><p>${t('前四项相加等于总盈亏。手续费已计入资产，不再额外加到收益上。','The first four items sum to total P&L. Fees are already included in assets, never added twice.')}</p>${feeContributionTable(p,o)}${state.view==='result'?feeDecisionBridge(r,old,p.day):''}<h3>${t('触发与交易记录','Triggers & trade records')}</h3>${eventTable(r.events,p.day)}<h3>${t('计算边界','Simulation limits')}</h3><p>${t('固定年化假设，不模拟成交量竞争。股价路径是构造情景，无杠杆、零摩擦成本；不是历史回测或收益预测。','Fixed fee-rate assumptions do not model volume competition. Paths are constructed, unlevered and frictionless; not historical backtests or return forecasts.')}</p>`;
    return '';
  }
  return {home,plan,run,runResult,endingTag,review,reviewResult,result,resultPanels,resultDay,comparisonSnapshot,evidence,library,future,details};
}
